/* NandBank — frontend autónomo, sem npm/CDN. HTML escapado, roles aplicados no servidor. */
'use strict';
function newUUID(){
  if(crypto.randomUUID)return crypto.randomUUID();
  const a=new Uint8Array(16);crypto.getRandomValues(a);a[6]=(a[6]&15)|64;a[8]=(a[8]&63)|128;
  const h=Array.from(a,x=>x.toString(16).padStart(2,'0')).join('');
  return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`;
}
const state={publicPage:'landing',cards:[],nodeActions:{agent_online:false,jobs:[]},token:sessionStorage.getItem('gs_token')||'',config:{regions:[],currencies:[]},profile:null,accounts:[],transfers:[],stats:null,nodes:[],operations:[],adminAccounts:[],rates:[],failover:[],page:'dashboard',lastUpdate:'—',mobileNav:false,visible:true,beneficiary:null,quote:null,receipt:null,accountSelected:null,key:newUUID(),tellerKey:newUUID(),busy:false};
const $=id=>document.getElementById(id);
const safe=x=>String(x==null?'':x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ico=(name,size=20)=>{const p={globe:'<circle cx="12" cy="12" r="10"/><path d="M2 12h20M12 2a15 15 0 0 0 0 20M12 2a15 15 0 0 1 0 20"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18M17 14h2"/>',transfer:'<path d="M4 7h16M15 2l5 5-5 5M20 17H4M9 12l-5 5 5 5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M23 21v-2a4 4 0 0 0-3-3.87"/><circle cx="8.5" cy="7" r="4"/>',shield:'<path d="m12 22 7-4V6l-7-4-7 4v12l7 4Z"/><path d="m9 12 2 2 4-4"/>',activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',server:'<rect x="3" y="3" width="18" height="8" rx="2"/><rect x="3" y="13" width="18" height="8" rx="2"/><path d="M7 7h.01M7 17h.01"/>',history:'<path d="M3 12a9 9 0 1 0 3-7M3 3v5h5M12 7v5l4 2"/>',receipt:'<path d="M4 3h16v18l-3-2-3 2-3-2-3 2-4-2zM8 8h8M8 12h8"/>',check:'<circle cx="12" cy="12" r="10"/><path d="m8 12 3 3 5-6"/>',alert:'<path d="m12 2 10 18H2L12 2ZM12 9v4M12 17h.01"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',logout:'<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9"/>',plus:'<path d="M12 5v14M5 12h14"/>',bank:'<path d="m3 10 9-7 9 7H3ZM4 21h16M6 10v8M10 10v8M14 10v8M18 10v8"/>',coins:'<circle cx="9" cy="9" r="6"/><path d="M15 6a7 7 0 1 1-9 11M9 6v6M6 9h6"/>',refresh:'<path d="M20 7v-4l-4 4M4 17v4l4-4M5 10a8 8 0 0 1 14-3M19 14A8 8 0 0 1 5 17"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 19v2h16v-2"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',x:'<path d="M4 4l16 16M20 4L4 20"/>',eye:'<path d="M2 12s3.8-7 10-7 10 7 10 7-3.8 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>',chart:'<path d="M3 3v18h18M7 17v-4M12 17V7M17 17v-8"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M4.9 4.9 7 7M17 17l2.1 2.1M19.1 4.9 17 7M7 17l-2.1 2.1"/>',right:'<path d="M5 12h14m-6-6 6 6-6 6"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[name]||p.globe}</svg>`};
const cash=(minor,currency)=>minor===null||minor===undefined?'Indisponível':new Intl.NumberFormat('pt-PT',{style:'currency',currency:currency||'MZN'}).format(Number(minor)/100);
const branchName=code=>state.config.regions.flatMap(r=>r.branches).find(b=>b.code===code)?.city||code||'—';
const regionName=code=>state.config.regions.find(r=>r.code===code)?.name||code?.toUpperCase()||'—';
const roleName={client:'Cliente',teller:'Operador de balcão',branch_manager:'Gerente de filial',regional_manager:'Gerente regional',global_manager:'Gerente global'};
const statusText={COMMITTED:'Concluída',ABORTED:'Recusada',PENDING:'Pendente',PREPARING:'Preparação',DECISION_COMMIT:'Confirmação pendente',DECISION_ABORT:'A cancelar',NEW:'Recebida'};
const person=()=>state.profile?.user;
const staff=()=>person()?.role!=='client';
const globalManager=()=>person()?.role==='global_manager';
const opts=(items,value,caption)=>items.map(i=>`<option value="${safe(i[value])}">${safe(caption(i))}</option>`).join('');
const prettyDate=s=>new Date(s).toLocaleString('pt-PT');
const statusBadge=s=>`<span class="status-pill ${safe((s||'').toLowerCase())}">${safe(statusText[s]||s)}</span>`;
function show(msg,type='success'){
 let box=$('notice');if(!box){box=document.createElement('div');box.id='notice';document.body.appendChild(box)}
 box.className='toast '+type;box.innerHTML=`${ico(type==='success'?'check':'alert',17)}<span>${safe(msg)}</span><button onclick="document.getElementById('notice').remove()">${ico('x',15)}</button>`;
 setTimeout(()=>{if(box.isConnected)box.remove()},6500);
}
async function request(path,options={}){
 const headers={...options.headers};if(state.token)headers.Authorization='Bearer '+state.token;
 if(options.body && typeof options.body==='string')headers['Content-Type']='application/json';
 let r;try{r=await fetch(path,{cache:'no-store',...options,headers})}catch{throw Error('Sem ligação ao PC servidor. Confirma a rede e o Docker.')}
 if(r.status===401&&path!=='/api/auth/login'){logout();throw Error('Sessão expirada. Entra novamente.')}
 if(!r.ok){let data={};try{data=await r.json()}catch{};throw Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail||'Falha'))}
 return r.status===204?null:r.json();
}
const formValue=id=>$(id)?.value||'';
const jsonPost=(path,data)=>request(path,{method:'POST',body:JSON.stringify(data)});
const select=(value,items,getValue,getLabel)=>items.map(i=>`<option value="${safe(getValue(i))}" ${getValue(i)===value?'selected':''}>${safe(getLabel(i))}</option>`).join('');
function getAuth(){
 const branches=state.config.regions.find(r=>r.code==='af')?.branches||[];
 return `<main class="auth-layout"><section class="auth-brand"><div class="wordmark big"><div class="brand-icon"><img src="/lion-mark.png" alt="NandBank" class="brand-lion"></div><div>NandBank<small>BANCO DIGITAL GLOBAL DISTRIBUÍDO</small></div></div><div class="auth-copy"><div class="eyebrow">BANCA GLOBAL, SEM FRONTEIRAS</div><h1>O teu dinheiro.<br><em>Uma ligação ao mundo.</em></h1><p>Abre a tua conta, consulta saldos em várias moedas e transfere entre continentes — com segurança e transparência.</p></div><div class="auth-feature"><div>${ico('globe')} Seis regiões interligadas</div><div>${ico('shield')} Privacidade e segurança</div><div>${ico('transfer')} Câmbio e transferências globais</div></div><div class="planet">${ico('globe',180)}</div></section>
 <section class="auth-side"><div class="auth-card"><div class="mobile-wordmark"><img src="/lion-mark.png" alt="" class="brand-lion"> NandBank</div><div class="eyebrow subtle">ÁREA SEGURA</div><h2 id="authTitle">Bem-vindo de volta</h2><p class="muted">Acede à tua conta ou cria uma conta na tua região.</p><div class="auth-tabs"><button id="tabLogin" class="selected" onclick="toggleAuth(false)">Entrar</button><button id="tabRegister" onclick="toggleAuth(true)">Criar conta</button></div>
 <form class="form" id="loginForm" onsubmit="login(event)"><label>Email<input id="loginEmail" type="email" autocomplete="username" required placeholder="nome@email.com"></label><label>Palavra-passe<input id="loginPassword" type="password" autocomplete="current-password" required placeholder="A tua palavra-passe"></label><button class="btn btn-main full">${ico('shield',17)} Entrar na conta</button><div class="hint">Os gerentes e operadores são criados pelo script de instalação no PC Windows.</div></form>
 <form class="form" id="registerForm" hidden onsubmit="register(event)"><label>Nome completo<input id="regName" required minlength="3" placeholder="Nome e apelido"></label><label>Email<input id="regEmail" type="email" required placeholder="nome@email.com"></label><label>Continente<select id="regRegion" onchange="setBranches()">${opts(state.config.regions,'code',r=>r.name)}</select></label><label>Filial<select id="regBranch" onchange="updateRegisterCurrency()">${opts(branches,'code',b=>b.city+' · '+b.country)}</select></label><label>Moeda definida pela filial<input id="regCurrency" value="${safe(branches[0]?.suggested_currency||'MZN')}" readonly></label><label>Palavra-passe<input type="password" id="regPassword" minlength="12" required placeholder="12+ caracteres, maiúscula/minúscula/número"></label><button class="btn btn-main full">${ico('plus',17)} Criar conta bancária</button><div class="hint">Saldo inicial zero. Depósitos de balcão exigem autorização de um operador.</div></form><div class="auth-footer">${ico('shield',15)} Demonstração segura: nenhum dinheiro real é movimentado.</div></div></section></main>`;
}
function toggleAuth(reg){$('loginForm').hidden=reg;$('registerForm').hidden=!reg;$('authTitle').textContent=reg?'Cria a tua conta':'Bem-vindo de volta';$('tabLogin').classList.toggle('selected',!reg);$('tabRegister').classList.toggle('selected',reg)}
function setBranches(){const region=formValue('regRegion');const list=state.config.regions.find(r=>r.code===region)?.branches||[];$('regBranch').innerHTML=opts(list,'code',b=>b.city+' · '+b.country);$('regCurrency').value=list[0]?.suggested_currency||''}
function updateRegisterCurrency(){const branch=formValue('regBranch');const item=state.config.regions.flatMap(r=>r.branches).find(b=>b.code===branch);$('regCurrency').value=item?.suggested_currency||''}
function updateNewAccountCurrency(){const branch=formValue('newAccountBranch');const item=state.config.regions.flatMap(r=>r.branches).find(b=>b.code===branch);$('newAccountCurrency').value=item?.suggested_currency||''}
async function login(e){e.preventDefault();try{const result=await jsonPost('/api/auth/login',{email:formValue('loginEmail'),password:formValue('loginPassword')});state.token=result.access_token;sessionStorage.setItem('gs_token',state.token);await sync();show('Bem-vindo ao NandBank.')}catch(err){show(err.message,'error')}}
async function register(e){e.preventDefault();try{await jsonPost('/api/auth/register',{name:formValue('regName'),email:formValue('regEmail'),password:formValue('regPassword'),branch:formValue('regBranch'),currency:formValue('regCurrency')});$('loginEmail').value=formValue('regEmail');$('loginPassword').value=formValue('regPassword');toggleAuth(false);show('Conta criada com saldo zero. Entra para começar.')}catch(err){show(err.message,'error')}}
function logout(){state.token='';sessionStorage.removeItem('gs_token');state.profile=null;state.page='dashboard';render()}
function navItems(){const base=[['dashboard','Visão geral','chart']];if(staff()){base.push(['cards','Aprovação de cartões','wallet'],['nodes','Nós continentais','server'],['ops','Transacções','transfer'],['clients','Contas e filiais','users'],['teller','Operações de balcão','bank'],['exchange','Moedas e câmbio','coins'])}else{base.push(['accounts','As minhas contas','wallet'],['cards','Cartões digitais','wallet'],['transfer','Transferir','transfer'],['movements','Movimentos','history'])}base.push(['services','Serviços','bank'],['about','Sobre o sistema','globe']);return base}
function header(){
 const nav=navItems().map(([name,label,icon])=>`<button type="button" class="${state.page===name?'active':''}" data-nav="${name}">${ico(icon,19)}<span>${safe(label)}</span></button>`).join('');
 const names={dashboard:'Visão geral',accounts:'As minhas contas',cards:staff()?'Aprovação de cartões':'Cartões digitais',transfer:'Transferências internacionais',movements:'Movimentos e extractos',nodes:'Infraestrutura e nós',ops:'Transferências',clients:'Contas e filiais',teller:'Operações de balcão',exchange:'Moedas e câmbio',services:'Serviços disponíveis',receipt:'Comprovativo',about:'Sobre o NandBank'};
 const role=person()?.role;
 const managingRegion=role==='regional_manager'?regionName(person()?.region):null;
 const title=state.page==='dashboard'?(managingRegion?'Operação da Região '+managingRegion:staff()?'Operações do NandBank':'Olá, '+person().name.split(' ')[0]+'!'):names[state.page]||'NandBank';
 const subtitle=staff()?'Monitorização, continuidade de serviço e operações autorizadas.':'Consulta as tuas contas e gere o teu dinheiro num só lugar.';
 return `<aside class="sidebar ${state.mobileNav?'open':''}"><div class="wordmark nb-wordmark"><img src="/lion-mark.png" alt="" class="brand-lion"><div>NandBank<small>BANCO DIGITAL GLOBAL</small></div></div><div class="role-chip"><div class="avatar">${safe(person().name[0])}</div><div class="nb-user"><b>${safe(person().name)}</b><small>${safe(roleName[role])}</small></div></div><div class="nav-caption">NAVEGAÇÃO</div><nav class="nav-menu" aria-label="Navegação principal">${nav}</nav><div class="nav-bottom"><div class="nb-network"><span class="health-dot"></span><span>Rede NandBank</span><strong>Ligada</strong></div><button type="button" id="logout">${ico('logout',18)} Terminar sessão</button></div></aside>${state.mobileNav?'<div class="mobile-overlay" id="overlay"></div>':''}<div class="main-shell"><header class="topbar nb-topbar"><button type="button" aria-label="Abrir menu" id="hamburger" class="mobile-menu icon-btn">${ico('menu',22)}</button><div class="nb-topbar-ident"><span class="top-hint">${staff()?'PAINEL DE GESTÃO':'ÁREA PESSOAL'}</span><span class="header-title">${safe(names[state.page]||'Visão geral')}</span></div><div class="top-actions"><div class="sync-label"><span class="live-dot"></span><span>Actualizado ${safe(state.lastUpdate)}</span></div><button type="button" class="icon-btn" id="refresh" aria-label="Actualizar dados" title="Actualizar dados">${ico('refresh',18)}</button><div class="top-avatar" title="${safe(roleName[role])}">${safe(person().name[0])}</div></div></header><main class="content nb-content"><div class="page-heading nb-page-heading"><div><div class="eyebrow">${staff()?'GESTÃO REGIONAL E GLOBAL':'BEM-VINDO AO NANDBANK'}</div><h1>${safe(title)}</h1><p>${safe(subtitle)}</p></div><button type="button" class="btn btn-ghost refresh" id="manual-refresh">${ico('refresh',16)} Actualizar</button></div>`;
}
function footer(){return `</main><footer class="app-footer">© 2026 NandBank · ISUTC <span>Simulação académica — sem ligação a bancos reais.</span></footer></div>${!staff()?`<nav class="bottom-nav">${[['dashboard','Início','chart'],['accounts','Contas','wallet'],['cards','Cartões','wallet'],['services','Serviços','bank'],['transfer','Transferir','transfer'],['movements','Histórico','history']].map(([n,l,i])=>`<button class="${state.page===n?'active':''}" data-nav="${n}">${ico(i,20)}${l}</button>`).join('')}</nav>`:''}`}
function pageHeader(title,right=''){return `<div class="section-title"><h3>${title}</h3>${right}</div>`}
function transItem(t){return `<div class="transaction-item"><div class="trans-icon">${ico('transfer',17)}</div><div class="grow"><strong>${safe(regionName(t.source_region))} → ${safe(regionName(t.dest_region))}</strong><small>${prettyDate(t.created_at)}</small></div><div class="right"><strong>${cash(t.amount_minor,t.source_currency)}</strong>${statusBadge(t.status)}</div></div>`}
function activityBars(){
 const today=new Date();today.setHours(0,0,0,0);
 const days=Array.from({length:7},(_,i)=>{const dt=new Date(today);dt.setDate(dt.getDate()-6+i);return dt});
 const count=days.map(d=>(state.transfers||[]).filter(t=>{const a=new Date(t.created_at);return !Number.isNaN(+a)&&a.toDateString()===d.toDateString()}).length);
 const max=Math.max(1,...count);
 return `<div class="nb-activity-chart" role="img" aria-label="Número de transferências nos últimos sete dias">${days.map((d,i)=>`<div class="nb-chart-col"><span class="nb-chart-value">${count[i]}</span><div class="nb-chart-bar" style="height:${Math.max(6,Math.round(count[i]/max*112))}px"></div><small>${safe(d.toLocaleDateString('pt-PT',{weekday:'short'}))}</small></div>`).join('')}</div>`;
}
function dashboardClient(){
 const accounts=state.accounts||[];
 const current=accounts.find(a=>a.id===state.accountSelected)||accounts[0];
 const currentLabel=current?branchName(current.branch)+' · '+current.currency:'Nenhuma conta seleccionada';
 const hasMoney=current&&current.balance_minor!=null;
 const selection=accounts.map(a=>`<option value="${safe(a.id)}" ${a.id===current?.id?'selected':''}>${safe(branchName(a.branch))} · ${safe(a.currency)}</option>`).join('');
 return `<section class="nb-dashboard-lead"><div class="client-hero nb-balance-hero"><div class="nb-balance-inner"><div class="nb-balance-head"><span>${ico('wallet',19)} Saldo disponível</span><button type="button" id="toggleBalance" class="nb-eye" aria-label="${state.visible?'Ocultar':'Mostrar'} saldo">${ico('eye',20)}</button></div><h2>${current?(state.visible?cash(current.balance_minor,current.currency):'••••••••'):'Sem contas activas'}</h2><p>${safe(currentLabel)}</p><div class="nb-balance-actions"><button type="button" class="btn btn-main" data-nav="accounts" ${current?'':'disabled'}>Ver detalhes da conta ${ico('right',16)}</button>${current?`<button type="button" class="btn nb-outline-dark" data-account-details="${safe(current.id)}">${ico('copy',15)} Dados bancários</button>`:''}</div></div><div class="nb-balance-emblem">${ico('globe',170)}</div></div><div class="panel nb-actions-panel"><div class="nb-panel-top"><h3>Acções rápidas</h3><span>O essencial num toque</span></div><div class="quick-actions nb-quick-actions">${[['transfer','Transferir','transfer'],['accounts','Contas','wallet'],['cards','Cartões','wallet'],['movements','Movimentos','history'],['services','Serviços','bank']].map(([page,label,icon])=>`<button type="button" data-nav="${page}"><div>${ico(icon,23)}</div><span>${label}</span></button>`).join('')}</div></div></section>
 <section class="nb-section"><div class="nb-section-head"><div><h2>As minhas contas</h2><p>Contas por região e moeda, sem somar divisas diferentes.</p></div><button type="button" class="inline-link" data-nav="accounts">Ver todas ${ico('right',16)}</button></div><div class="accounts-grid nb-account-grid">${accounts.map(a=>`<article class="account-card nb-account-card ${a.id===current?.id?'selected':''}"><div class="nb-account-upper"><span class="nb-account-symbol">${ico('globe',22)}</span><span>${safe(a.currency)}</span></div><h3><button type="button" class="nb-account-select" data-account-select="${safe(a.id)}" title="Seleccionar conta">${safe(branchName(a.branch))}</button></h3><small>${safe(regionName(a.region))} · ${safe(a.currency)}</small><div class="nb-account-amount">${state.visible?cash(a.balance_minor,a.currency):'••••••••'}</div><div class="nb-account-footer"><span>${safe(a.id.slice(0,8))}…</span><div class="account-actions"><button type="button" data-account-details="${safe(a.id)}" title="Detalhes da conta" aria-label="Detalhes da conta">${ico('receipt',17)}</button><button type="button" data-copy="${safe(a.id)}" title="Copiar identificação" aria-label="Copiar identificação">${ico('copy',16)}</button></div></div></article>`).join('')||'<div class="panel nb-empty-card">Ainda não tens contas. Cria uma conta através do registo.</div>'}</div></section>
 ${failoverNotice(false)}
 <section class="nb-summary-grid"><div class="panel nb-chart-panel"><div class="nb-panel-top"><div><h3>Actividade de transferências</h3><p>Operações registadas nos últimos 7 dias</p></div><span class="nb-data-chip">Dados reais</span></div>${activityBars()}<small class="nb-panel-foot">Contagem baseada no histórico da conta. Não representa evolução do saldo.</small></div><div class="panel nb-recent-panel"><div class="nb-panel-top"><div><h3>Movimentos recentes</h3><p>As últimas transferências registadas</p></div><button type="button" class="inline-link" data-nav="movements">Ver todos ${ico('right',15)}</button></div><div class="nb-recent-list">${(state.transfers||[]).slice(0,5).map(transItem).join('')||'<div class="nb-data-empty">Ainda não existem transferências nesta conta.</div>'}</div></div></section>`;
}
function dashboardManager(){
 const stats=state.stats||{},tr=stats.transfers||{},op=stats.operations||{};
 const nodes=state.nodes||[],up=nodes.filter(n=>n.service_available).length;
 const metrics=[['Clientes registados',stats.clients??'—','users'],['Regiões disponíveis',up+' / '+nodes.length,'server'],['Transferências concluídas',tr.COMMITTED||0,'check'],['Operações pendentes',(tr.PENDING||0)+(tr.DECISION_COMMIT||0),'activity']];
 const events=(state.nodeActions?.jobs||[]).slice(0,5);
 return `${failoverNotice(true)}<div class="nb-metrics metrics">${metrics.map(([label,value,icon])=>`<div class="metric nb-metric"><div class="metric-icon">${ico(icon,22)}</div><small>${safe(label)}</small><b>${safe(value)}</b><span>Dados do sistema</span></div>`).join('')}</div>
 <div class="nb-manager-grid"><section class="panel nb-infra-panel"><div class="nb-panel-top"><div><h3>Estado da infraestrutura</h3><p>Nós principais, secundários e disponibilidade actual</p></div><button type="button" class="inline-link" data-nav="nodes">Gerir nós ${ico('right',16)}</button></div><div class="nb-node-list">${nodes.map(n=>`<article class="nb-node-row"><div class="nb-node-region">${ico('globe',22)}<div><b>${safe(n.name)}</b><small>${n.status==='FAILOVER'?'Failover activo':n.status==='UP'?'Operação normal':n.status==='RECOVERING'?'Em recuperação':n.status==='CHECKING'?'A verificar':'Indisponível'}</small></div></div><div class="nb-node-replicas"><span class="nb-node-status ${n.primary_status==='UP'?'ok':'bad'}">${ico('server',15)} Principal: ${n.primary_status==='UP'?'Activo':n.primary_status==='DOWN'?'Indisponível':'A verificar'}</span><span class="nb-node-status ${n.standby_status==='UP'?'ok':'bad'}">${ico('server',15)} Secundário: ${n.standby_status==='UP'?'Activo':n.standby_status==='DOWN'?'Indisponível':'A verificar'}</span></div><span class="nb-availability ${n.service_available?'ok':'bad'}">${n.service_available?'Disponível':'Sem serviço'}</span></article>`).join('')||'<div class="nb-data-empty">Ainda não foi possível consultar os nós.</div>'}</div><div class="nb-panel-foot">O nó secundário assume a aplicação quando o principal falha. Ambos utilizam a mesma base de dados regional.</div></section>
 <section class="panel nb-events-panel"><div class="nb-panel-top"><div><h3>Intervenções recentes</h3><p>Pedidos registados de gestão de nós</p></div><span class="nb-agent-state ${state.nodeActions?.agent_online?'online':'offline'}">${state.nodeActions?.agent_online?'Agente ligado':'Agente por verificar'}</span></div>${events.map(j=>`<div class="nb-event"><span class="nb-event-dot"></span><div><b>${safe(regionName(j.region))} · ${j.action==='STOP_PRIMARY'?'Paragem do principal':'Reinício do principal'}</b><small>${safe(j.reason||'Sem motivo')} · ${safe(j.status||'Pendente')}</small></div><time>${safe(prettyDate(j.created_at))}</time></div>`).join('')||'<div class="nb-data-empty">Sem intervenções registadas.</div>'}<button type="button" class="btn btn-ghost nb-block-button" data-nav="nodes">${ico('settings',17)} Abrir controlo de nós</button></section></div>
 <section class="panel nb-ops-strip"><h3>Resumo de operações</h3><div><span>Depósitos <b>${safe(op.DEPOSIT||0)}</b></span><span>Levantamentos <b>${safe(op.WITHDRAW||0)}</b></span><span>Transferências recusadas <b>${safe(tr.ABORTED||0)}</b></span><span>Moedas monitorizadas <b>${state.rates.length}</b></span></div></section>`;
}
function accountsPage(){return `<div class="panel" style="padding:24px">${pageHeader('As minhas contas','<span class="muted">Copia o identificador para receber transferências.</span>')}${state.accounts.map(a=>`<div class="account-detail"><div><div class="eyebrow">${safe(regionName(a.region))} · ${safe(branchName(a.branch))}</div><h3>${cash(a.balance_minor,a.currency)}</h3><p>Saldo disponível · ${safe(a.currency)}</p><code>${safe(a.id)}</code></div><div class="account-detail-actions"><button class="btn btn-ghost" data-account-details="${safe(a.id)}">${ico('receipt',15)} Ver dados da conta</button><button class="btn btn-ghost" data-copy="${safe(a.id)}">${ico('copy',15)} Copiar conta</button></div></div>`).join('')}</div><div class="panel" style="padding:23px;margin-top:18px">${pageHeader('Criar outra conta bancária')}<form class="form" id="additionalAccountForm"><label>Filial<select id="newAccountBranch" onchange="updateNewAccountCurrency()">${state.config.regions.flatMap(r=>r.branches.map(b=>`<option value="${safe(b.code)}">${safe(r.name)} · ${safe(b.city)}</option>`)).join('')}</select></label><label>Moeda definida pela filial<input id="newAccountCurrency" value="${safe(state.config.regions.flatMap(r=>r.branches).find(b=>b.code===state.config.regions[0]?.branches?.[0]?.code)?.suggested_currency||'MZN')}" readonly></label><button class="btn btn-main full">${ico('plus',16)} Criar conta com saldo zero</button></form></div>`}
function transferPage(){const src=state.accounts[0];return `${failoverNotice(false)}<div class="transfer-layout"><div class="panel form-panel">${pageHeader('Nova transferência','<span class="step-label">Passo 1 de 2</span>')}<form class="form" id="transferForm"><label>Conta de origem<select id="transferSource">${select('',state.accounts,a=>a.id,a=>branchName(a.branch)+' · '+a.currency+' · '+a.id.slice(0,8))}</select></label><label>Conta do beneficiário<div class="inline-input"><input id="transferDest" placeholder="Cole o identificador da conta" required><button class="btn btn-ghost" type="button" id="verifyDest">Verificar</button></div></label><div id="beneficiaryResult"></div><label>Montante a enviar<input id="transferAmount" type="number" min="0.01" step="0.01" required placeholder="0,00"></label><label>Descrição opcional<input id="transferNote" maxlength="400" placeholder="Motivo da transferência"></label><button class="btn btn-main full">${ico('coins',17)} Calcular valor e comissões</button></form></div><div class="panel quote-panel">${pageHeader('Resumo da transferência',ico('shield',21))}<div id="quoteResult" class="empty-quote">${ico('globe',68)}<h3>Transfere sem fronteiras</h3><p>Introduz o beneficiário e o montante para conhecer a taxa de câmbio, comissões e valor final.</p></div></div></div>`}
function receiptPage(){const r=state.receipt;if(!r)return '<div class="empty">Sem operação seleccionada.</div>';return `<div class="receipt-wrap"><div class="panel receipt-panel"><div class="receipt-icon ${r.status!=='COMMITTED'?'pending':''}">${ico(r.status==='COMMITTED'?'check':'refresh',44)}</div><h2>${r.status==='COMMITTED'?'Operação confirmada':'Operação em processamento'}</h2><p>${r.status==='COMMITTED'?'Transferência registada em ambas as contas.':'Estado pendente; não reenviar a mesma operação com outro ID.'}</p><div class="receipt-table"><div><span>Referência</span><strong>${safe(r.id)}</strong></div><div><span>Estado</span><strong>${safe(statusText[r.status]||r.status)}</strong></div>${r.quote?`<div><span>Valor debitado</span><strong>${safe(r.quote.total_debit)} ${safe(r.quote.source_currency)}</strong></div><div><span>Montante recebido</span><strong>${safe(r.quote.recipient_amount)} ${safe(r.quote.destination_currency)}</strong></div>`:''}</div>${r.status==='COMMITTED'?`<button id="getPDF" class="btn btn-main full">${ico('download',17)} Descarregar comprovativo PDF</button>`:''}<button class="btn btn-ghost full" data-nav="transfer">Nova transferência</button></div></div>`}
function movementsPage(){const acct=state.accounts.find(a=>a.id===state.accountSelected)||state.accounts[0];return `<div class="panel" style="padding:22px">${pageHeader('Movimentos da conta',`<select id="ledgerSelect" class="small-select">${select(acct?.id||'',state.accounts,a=>a.id,a=>branchName(a.branch)+' · '+a.currency)}</select>`)}<div id="ledgerData" class="empty">A carregar...</div></div><div class="panel" style="padding:22px">${pageHeader('Transferências')}${state.transfers.map(t=>`<div class="transaction-item"><div class="trans-icon">${ico('transfer',17)}</div><div class="grow"><strong>${safe(regionName(t.source_region))} → ${safe(regionName(t.dest_region))}</strong><small>${prettyDate(t.created_at)}</small></div>${statusBadge(t.status)}${t.status==='COMMITTED'?`<button class="icon-btn" data-pdf="${safe(t.id)}">${ico('download',17)}</button>`:''}</div>`).join('')||'<div class="empty">Sem movimentos.</div>'}</div>`}
function nodePageOriginal(){return `<section class="panel nb-nodes-page"><div class="nb-panel-top"><div><h3>Infraestrutura distribuída</h3><p>Estado actual dos nós e das respectivas instâncias</p></div><span class="nb-data-chip">${ico('refresh',14)} Actualização automática</span></div>${failoverNotice(true)}<div class="node-grid nb-node-cards">${state.nodes.map(n=>`<article class="node-card large nb-node-card"><div class="node-head">${ico('globe',24)}<span class="status-pill ${n.status==='DOWN'?'aborted':n.status==='FAILOVER'?'pending':'committed'}">${n.status==='UP'?'Operacional':n.status==='FAILOVER'?'Em failover':n.status==='RECOVERING'?'Em recuperação':n.status==='CHECKING'?'A verificar':'Indisponível'}</span></div><h3>${safe(n.name)}</h3><div class="nb-replica-row"><div class="nb-replica-mark ${n.primary_status==='UP'?'ok':'bad'}">${ico('server',19)}</div><div><strong>Nó principal</strong><small>${n.primary_status==='UP'?'Operacional':n.primary_status==='DOWN'?'Indisponível':'A verificar'}</small></div></div><div class="nb-replica-row"><div class="nb-replica-mark ${n.standby_status==='UP'?'ok':'bad'}">${ico('server',19)}</div><div><strong>Nó secundário</strong><small>${n.standby_status==='UP'?'Operacional':n.standby_status==='DOWN'?'Indisponível':'A verificar'}</small></div></div><div class="nb-node-meta"><span>Instância em serviço</span><b>${n.active_instance==='primary'?'Principal':n.active_instance==='standby'?'Secundária':'Nenhuma'}</b></div><div class="nb-node-meta"><span>Contas da região</span><b>${safe(n.accounts??'—')}</b></div>${n.write_blocked?`<div class="failover-warning">${ico('alert',15)} Escritas suspensas por ${safe(n.cooldown_remaining)} s</div>`:''}<p class="node-message">${safe(n.message||'')}</p></article>`).join('')}</div><div class="nb-panel-foot">A alta disponibilidade apresentada refere-se aos serviços da aplicação; não implica replicação automática da base de dados PostgreSQL.</div></section>`}
function serviceCard(title,description,icon,page,meta='Disponível'){return `<button class="service-card" data-nav="${safe(page)}"><span class="service-icon">${ico(icon,25)}</span><span class="service-copy"><b>${safe(title)}</b><small>${safe(description)}</small></span><span class="service-meta">${safe(meta)} ${ico('right',14)}</span></button>`}
function serviceInfoCard(title,description,icon,meta){return `<div class="service-card service-card-static"><span class="service-icon">${ico(icon,25)}</span><span class="service-copy"><b>${safe(title)}</b><small>${safe(description)}</small></span><span class="service-meta">${safe(meta)}</span></div>`}
function servicesPage(){
 if(staff())return `<div class="service-group"><h3>Gestão e monitorização</h3><div class="services-grid">${serviceCard('Contas e clientes','Consultar clientes, contas e filiais.','users','clients')}${serviceCard('Operações de balcão','Registar depósitos e levantamentos autorizados.','bank','teller')}${serviceCard('Transferências','Acompanhar transferências e respectivos estados.','transfer','ops')}${serviceCard('Nós continentais','Ver os servidores principal e secundário.','server','nodes')}${serviceCard('Moedas e câmbio','Consultar e gerir as cotações demonstrativas.','coins','exchange')}${serviceCard('Histórico operacional','Consultar movimentos e operações registadas.','history','ops')}</div></div><div class="hint">As permissões de cada serviço dependem do perfil e do âmbito geográfico da sessão.</div>`;
 return `<div class="service-group"><h3>Contas</h3><div class="services-grid">${serviceCard('Consultar contas','Ver saldo na moeda da filial e movimentos.','wallet','accounts')}${serviceCard('Abrir conta','Criar outra conta na moeda definida pela filial.','plus','accounts')}${serviceCard('Dados bancários','Consultar NIB, IBAN e identificadores demonstrativos.','receipt','accounts')}</div></div><div class="service-group"><h3>Transferências e operações</h3><div class="services-grid">${serviceCard('Transferência nacional','Enviar dinheiro entre contas da mesma região.','transfer','transfer')}${serviceCard('Transferência internacional','Enviar dinheiro entre continentes com conversão.','globe','transfer')}${serviceCard('Câmbio integrado','Ver taxa, comissão e montante a receber antes de confirmar.','coins','transfer')}${serviceCard('Histórico e comprovativos','Consultar operações e descarregar comprovativos.','history','movements')}</div></div><div class="service-group"><h3>Serviços de balcão</h3><div class="services-grid">${serviceInfoCard('Depósitos','Realizados por um operador autorizado no balcão.','bank','No balcão')}${serviceInfoCard('Levantamentos','Realizados por um funcionário autorizado no balcão.','receipt','No balcão')}</div></div><p class="hint">Pagamentos de serviços, recargas móveis e cartões não estão activos nesta versão académica e não serão apresentados como operações disponíveis.</p>`;
}
function failoverNotice(manager=false){
 const id=manager?'managerFailoverNotice':'clientFailoverNotice';
 const items=(manager?state.nodes:state.failover).filter(n=>n.primary_status==='DOWN'||n.status==='DOWN'||n.status==='FAILOVER'||n.status==='RECOVERING');
 if(!items.length)return `<div id="${id}"></div>`;
 return `<div id="${id}" class="failover-notice ${manager?'manager':''}">${ico('alert',21)}<div><b>${manager?'Alerta de infraestrutura':'Aviso temporário de serviço'}</b>${items.map(n=>`<p><strong>${safe(n.name||regionName(n.region))}:</strong> ${safe(n.message||'Servidor principal indisponível; o secundário está a assumir o serviço.')}</p>`).join('')}</div></div>`;
}
async function openAccountDetails(accountId){
 try{
  const d=await request('/api/accounts/'+encodeURIComponent(accountId)+'/details');
  const rows=[
   ['Titular',d.owner_name],['Banco',d.bank_name],['Número da conta',d.account_number],
   ['NIB demonstrativo',d.nib||'Não aplicável nesta filial'],['IBAN demonstrativo',d.iban||'Não aplicável nesta filial'],
   ['SWIFT / BIC demonstrativo',d.swift_bic],['País',d.country],['Continente',d.region],
   ['Filial',d.branch_name+' ('+d.branch+')'],['Tipo de conta',d.account_type],
   ['Moeda',d.currency],['Saldo disponível',cash(d.balance_minor,d.currency)],['Estado',d.status]
  ];
  const modal=document.createElement('div');modal.className='modal-backdrop';
  modal.innerHTML=`<section class="account-modal" role="dialog" aria-modal="true" aria-labelledby="accountModalTitle"><div class="modal-head"><div><div class="eyebrow">DADOS BANCÁRIOS</div><h2 id="accountModalTitle">Detalhes da conta</h2></div><button class="icon-btn" id="closeAccountModal" aria-label="Fechar">${ico('x',20)}</button></div><div class="account-modal-grid">${rows.map(([label,value])=>`<div class="account-modal-field"><small>${safe(label)}</small><b>${safe(value)}</b></div>`).join('')}</div><div class="modal-notice">${ico('shield',16)} ${safe(d.notice)}</div><div class="modal-actions"><button class="btn btn-ghost" id="copyAccountId">${ico('copy',15)} Copiar identificador</button><button class="btn btn-main" id="closeAccountModal2">Fechar</button></div></section>`;
  document.body.appendChild(modal);
  const close=()=>modal.remove();
  modal.addEventListener('click',e=>{if(e.target===modal)close()});
  modal.querySelector('#closeAccountModal').addEventListener('click',close);
  modal.querySelector('#closeAccountModal2').addEventListener('click',close);
  modal.querySelector('#copyAccountId').addEventListener('click',()=>copyValue(d.account_id));
 }catch(e){show(e.message,'error')}
}
async function normalizeCurrencies(){
 if(!globalManager()||!confirm('Normalizar as contas antigas para a moeda definida pela filial? Os saldos serão convertidos pela cotação demonstrativa actual. Os movimentos anteriores serão preservados e registada uma linha de conversão.'))return;
 try{
  const r=await jsonPost('/api/admin/accounts/normalize-currencies',{});
  show(r.message||'Normalização concluída.');
  if(r.failures?.length)show(`${r.failures.length} conta(s) não puderam ser normalizadas. Consulte os detalhes na resposta da operação.`,'warning');
  await sync();
 }catch(e){show(e.message,'error')}
}

function table(headers,rows){return `<div class="responsive-table"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>${rows.length?'':'<div class="empty">Sem registos.</div>'}`}
function opsPage(){return `<div class="panel" style="padding:22px">${pageHeader('Transferências','<span class="muted">2PC global · ACID local</span>')}${table(['Referência','Origem → Destino','Montante','Recebido','Estado','Data','PDF'],state.transfers.map(t=>`<tr><td><code>${safe(t.id.slice(0,10))}</code></td><td>${safe(regionName(t.source_region))} → ${safe(regionName(t.dest_region))}</td><td>${cash(t.amount_minor,t.source_currency)}</td><td>${cash(t.credit_minor,t.dest_currency)}</td><td>${statusBadge(t.status)}</td><td>${prettyDate(t.created_at)}</td><td>${t.status==='COMMITTED'?`<button class="icon-btn" data-pdf="${safe(t.id)}">${ico('download',16)}</button>`:''}</td></tr>`))}</div><div class="panel" style="padding:22px">${pageHeader('Depósitos e levantamentos')}${table(['Referência','Operação','Montante creditado','Moeda','Filial','Estado'],state.operations.map(o=>`<tr><td><code>${safe(o.id.slice(0,10))}</code></td><td>${o.operation_type==='DEPOSIT'?'Depósito':'Levantamento'}</td><td>${cash(o.credited_minor,o.account_currency)}</td><td>${safe(o.account_currency)}</td><td>${safe(branchName(o.branch))}</td><td>${statusBadge(o.status)}</td></tr>`))}</div>`}
function clientsPage(){return `<div class="panel" style="padding:22px">${pageHeader('Contas e filiais','<span class="muted">Copie o identificador para efectuar depósitos</span>')}${table(['Cliente','Conta','Continente','Filial','Moeda','Dados / copiar'],state.adminAccounts.map(a=>`<tr><td><strong>${safe(a.name)}</strong><small class="cell-small">${safe(a.email)}</small></td><td><code>${safe(a.id.slice(0,12))}</code></td><td>${safe(regionName(a.region))}</td><td>${safe(branchName(a.branch))}</td><td>${safe(a.currency)}</td><td><div class="account-actions"><button class="icon-btn" data-copy="${safe(a.id)}" title="Copiar conta">${ico('copy',17)}</button><button class="icon-btn" data-account-details="${safe(a.id)}" title="Ver dados bancários">${ico('receipt',17)}</button></div></td></tr>`))}</div>`}
function tellerPage(){return `<div class="transfer-layout"><div class="panel form-panel">${pageHeader('Operação de balcão',ico('bank',21))}<form id="tellerForm" class="form"><label>Tipo<select id="tellerKind"><option value="DEPOSIT">Depósito</option><option value="WITHDRAW">Levantamento</option></select></label><label>Conta<input required id="tellerAccount" placeholder="Identificador completo da conta"></label><label>Montante<input required id="tellerAmount" min="0.01" step="0.01" type="number" placeholder="0,00"></label><label>Moeda recebida<select id="tellerCurrency">${state.config.currencies.map(c=>`<option>${safe(c)}</option>`).join('')}</select></label><button class="btn btn-main full">${ico('bank',17)} Registar operação</button></form></div><div class="panel" style="padding:25px">${pageHeader('Regras bancárias')}<div class="guidance">${ico('shield',29)}<p>Depósitos e levantamentos requerem um perfil autorizado. O servidor verifica o âmbito da filial.</p><p>Depósitos em moedas diferentes são convertidos para a moeda da conta com a taxa actual.</p><p>A chave de idempotência impede duplicação após falhas e tentativas repetidas.</p></div></div></div>`}
function exchangePage(){return `<div class="two-panels"><div class="panel">${pageHeader('Taxas por moeda',ico('coins',21))}${state.rates.map(r=>`<div class="rate-row"><b>${safe(r.currency)}</b><span>1 EUR = ${safe(r.units_per_eur)} ${safe(r.currency)}</span><span class="rate-origin">${safe(r.source)}</span></div>`).join('')}${globalManager()?`<button class="btn btn-ghost full" id="refreshFx">${ico('refresh',16)} Consultar fonte externa</button>`:''}</div><div class="panel">${pageHeader(globalManager()?'Definir cotação demonstrativa':'Cotações do sistema')}${globalManager()?`<form class="form" id="fxEditForm"><label>Moeda<select id="fxEditCurrency">${state.config.currencies.map(c=>`<option>${safe(c)}</option>`).join('')}</select></label><label>Unidades por 1 EUR<input id="fxEditValue" type="number" min="0.00001" step="any" value="${safe(state.rates.find(r=>r.currency==='MZN')?.units_per_eur||'70.11')}" required></label><button class="btn btn-main full">${ico('coins',16)} Guardar taxa</button></form><div class="currency-normalize"><b>Contas antigas com moeda incorrecta</b><p>Converte contas existentes para a moeda definida pela respectiva filial. A operação usa a cotação demonstrativa e regista a conversão no histórico.</p><button class="btn btn-ghost full" id="normalizeCurrencies">${ico('refresh',16)} Normalizar moedas das contas</button></div>`:'<p class="muted">Só o gerente global altera as cotações.</p>'}<p class="hint">Cotações demonstrativas: não são taxas bancárias oficiais nem valores de mercado garantidos.</p></div></div>`}
function aboutPage(){return `<div class="panel" style="padding:23px">${pageHeader('O que está por trás da aplicação')}<div class="about-grid">${[['server','Seis nós continentais','Serviços e PostgreSQL independentes por continente no Docker Windows.'],['shield','Segurança','JWT RSA, HTTPS, mTLS, HMAC e PostgreSQL com TLS.'],['transfer','Transacções 2PC','Decisão durável, preparação em nós regionais e recuperação.'],['bank','Continuidade','HAProxy substitui processos regionais; falha física do PC exige outro host.']].map(([i,t,d])=>`<div>${ico(i,24)}<b>${t}</b><p>${d}</p></div>`).join('')}</div><p class="hint">Ambiente exclusivamente académico, sem contacto com bancos reais.</p></div>`}

function showLanding(){state.publicPage='landing';render();window.scrollTo(0,0)}
function showAuth(registerNow){state.publicPage='auth';render();if(registerNow)toggleAuth(true);window.scrollTo(0,0)}
function landingPage(){return `<div class="public-site nb-public">
 <header class="landing-nav nb-public-nav"><a href="#" onclick="event.preventDefault();showLanding()" class="landing-logo nb-public-logo"><img src="/lion-mark.png" alt=""><strong>NandBank</strong></a><nav aria-label="Navegação do site"><a href="#vantagens">Vantagens</a><a href="#solucoes">Soluções</a><a href="#experiencias">Experiências</a><a href="#seguranca">Segurança</a></nav><div class="landing-actions"><button type="button" class="outline" onclick="showAuth(false)">Entrar</button><button type="button" class="gold" onclick="showAuth(true)">Criar conta</button></div></header>
 <main><section class="nb-public-hero"><div class="nb-public-hero-inner"><div class="nb-public-copy"><span class="eyebrow">BANCO DIGITAL GLOBAL</span><h1>O seu dinheiro.<br><span>Em qualquer lugar.</span></h1><p>Contas em diferentes regiões, transferências internacionais e serviços digitais integrados. Uma experiência simples, mesmo numa rede distribuída.</p><div class="hero-buttons"><button type="button" class="gold" onclick="showAuth(true)">Criar conta ${ico('right',18)}</button><button type="button" class="outline" onclick="showAuth(false)">Entrar</button></div><div class="nb-hero-assurances"><span>${ico('shield',19)} Acesso protegido</span><span>${ico('server',19)} Continuidade de serviço</span><span>${ico('globe',19)} Seis continentes</span></div></div><div class="nb-public-photo"><img src="/nandbank-hero.webp" alt="Cliente a utilizar o telemóvel e um cartão bancário numa imagem ilustrativa"><span class="nb-photo-tag">${ico('globe',18)} NandBank · Uma experiência global</span></div></div></section>
 <section class="nb-public-benefits" id="vantagens"><article><span>${ico('wallet',25)}</span><div><h3>Contas regionais</h3><p>Gere contas e moedas de diferentes regiões.</p></div></article><article><span>${ico('transfer',25)}</span><div><h3>Transferências globais</h3><p>Movimenta valores entre continentes com câmbio.</p></div></article><article><span>${ico('shield',25)}</span><div><h3>Cartões digitais</h3><p>Pede e gere cartões de demonstração.</p></div></article><article><span>${ico('server',25)}</span><div><h3>Alta disponibilidade</h3><p>Nós de reserva mantêm a aplicação acessível.</p></div></article></section>
 <section class="nb-public-showcase" id="experiencias"><div class="nb-showcase-copy"><span class="eyebrow">EXPERIÊNCIAS NANDBANK</span><h2>Uma plataforma.<br><span>Dois modos de gestão.</span></h2><p>O cliente acompanha as suas finanças; os gerentes monitorizam operações, infraestrutura e continuidade de serviço.</p><ul><li>${ico('check',19)} Contas e transferências por moeda</li><li>${ico('check',19)} Aprovação de cartões por perfil</li><li>${ico('check',19)} Monitorização de nós e eventos de failover</li></ul><button type="button" class="nb-showcase-link" onclick="showAuth(false)">Conhecer o painel ${ico('right',17)}</button></div><div class="nb-previews"><div class="nb-preview nb-preview-client"><div class="nb-preview-toolbar"><span class="nb-preview-logo">${ico('wallet',16)} NandBank</span><small>CLIENTE</small></div><div class="nb-preview-title">As minhas contas</div><div class="nb-preview-amount">Saldo por conta e moeda</div><div class="nb-preview-sim-line"></div><div class="nb-preview-pills"><span>Transferir</span><span>Cartões</span><span>Movimentos</span></div><small>Pré-visualização ilustrativa</small></div><div class="nb-preview nb-preview-manager"><div class="nb-preview-toolbar"><span class="nb-preview-logo">${ico('server',16)} NandBank</span><small>GESTÃO</small></div><div class="nb-preview-title">Infraestrutura regional</div><div class="nb-preview-status"><span>${ico('check',16)} Principal operacional</span><span>${ico('check',16)} Secundário pronto</span></div><div class="nb-preview-tracks"><i></i><i></i><i></i><i></i></div><small>Pré-visualização ilustrativa</small></div></div></section>
 <section class="nb-public-solutions" id="solucoes"><div class="nb-public-section-title"><span class="eyebrow">FEITO PARA O DIA A DIA</span><h2>Simples para o cliente.<br>Preparado para crescer.</h2></div><div class="nb-solutions-list"><article><span>${ico('wallet',23)}</span><h3>Contas</h3><p>Saldo e dados bancários por filial.</p></article><article><span>${ico('transfer',23)}</span><h3>Transferências</h3><p>Operações locais e internacionais com comprovativo.</p></article><article><span>${ico('shield',23)}</span><h3>Segurança</h3><p>Autenticação e permissões hierárquicas.</p></article></div></section>
 <section class="nb-public-final" id="seguranca"><div><span class="eyebrow">NANDBANK · ISUTC</span><h2>Um banco digital distribuído.<br>Um projecto académico funcional.</h2><p>As operações são simuladas e não movimentam dinheiro real. As funções disponíveis dependem do perfil de acesso.</p></div><button type="button" class="gold" onclick="showAuth(true)">Começar agora ${ico('right',17)}</button></section></main>
 <footer class="landing-footer nb-public-footer"><a href="#" onclick="event.preventDefault();showLanding()" class="landing-logo"><img src="/lion-mark.png" alt=""><strong>NandBank</strong></a><span>© 2026 NandBank · Protótipo académico · Sem dinheiro real.</span></footer></div>`}
function nodeManagementPanel(){if(!['global_manager','regional_manager'].includes(person()?.role))return '';
 const options=state.nodes.map(n=>`<option value="${safe(n.region)}">${safe(n.name)} · ${safe(n.primary_status)} / ${safe(n.standby_status)}</option>`).join('');
 const recent=(state.nodeActions.jobs||[]).slice(0,6).map(j=>`<div class="transaction-item"><div class="grow"><strong>${safe(regionName(j.region))} — ${safe(j.action==='STOP_PRIMARY'?'Desligar principal':'Ligar principal')}</strong><small>${safe(j.reason)} · ${safe(prettyDate(j.created_at))}</small></div>${safe(j.status)}</div>`).join('')||'<div class="empty">Sem intervenções registadas.</div>';
 return `<div class="panel management-panel"><div class="section-title"><h3>Controlo de nós · Windows</h3><small>${state.nodeActions.agent_online?'Agente autorizado ligado':'Agente Windows desligado — inicia o sistema com INICIAR_WINDOWS.bat'}</small></div><p class="guidance">Só o gerente da região ou o gerente global podem solicitar a manutenção. O agente Windows desliga ou liga apenas a instância principal escolhida. A standby deve estar operacional.</p><form class="management-form" id="nodeControlForm"><label>Continente<select id="nodeActionRegion" required>${options}</select></label><label>Acção<select id="nodeActionType"><option value="STOP_PRIMARY">Desligar nó principal</option><option value="START_PRIMARY">Ligar nó principal</option></select></label><label>Motivo<select id="nodeActionReason"><option value="MAINTENANCE">Manutenção programada</option><option value="FAULT">Avaria interna</option><option value="SECURITY">Incidente de segurança</option><option value="UPGRADE">Actualização</option><option value="FAILOVER_TEST">Teste de tolerância a falhas</option><option value="OTHER">Outro</option></select></label><label>Observação<input id="nodeActionNote" maxlength="300" placeholder="Informação sobre a intervenção"></label><button class="btn btn-main" ${state.nodeActions.agent_online?'':'disabled'}>Confirmar intervenção</button></form><h3>Histórico de intervenções</h3>${recent}</div>`}
function nodePage(){return nodePageOriginal()+nodeManagementPanel()}
async function nodeControl(e){e.preventDefault();const region=formValue('nodeActionRegion'),action=formValue('nodeActionType'),reason=formValue('nodeActionReason');if(!window.confirm(`Confirmar ${action==='STOP_PRIMARY'?'paragem':'reinício'} do nó principal de ${regionName(region)}?`))return;try{await jsonPost('/api/admin/nodes/'+region+'/action',{action,reason,note:formValue('nodeActionNote')});show('Intervenção solicitada. A acompanhar a execução.');await sync()}catch(e){show(e.message,'error')}}
function cardVisual(c){return `<div class="card-scene"><button type="button" class="card-rotator ${c.status==='FROZEN'?'frozen':''}" data-card-flip="${safe(c.id)}" aria-label="Virar cartão virtual académico"><span class="card-face card-front"><span class="card-top"><img src="/lion-mark.png" alt=""><span>NandBank</span><small>CARTÃO ACADÉMICO</small></span><span class="card-chip">▦</span><span class="card-number">•••• &nbsp; •••• &nbsp; •••• &nbsp; ${safe(c.last4)}</span><span class="card-bottom"><span>${safe(c.holder_name)}</span><b>${safe(c.status)}</b></span></span><span class="card-face card-back"><span class="card-back-band"></span><span class="card-back-label">CVV: DEMO</span><span class="card-back-caption">Este não é um cartão de pagamento. Não existem PAN ou CVV válidos.</span><b>NandBank</b></span></button><span class="flip-instruction">↻ Clique para virar o cartão · Visualização académica</span></div>`}
function cardsPage(){if(staff()){
 if(!['global_manager','regional_manager'].includes(person()?.role))return '<div class="panel">Aprovação de cartões reservada aos gerentes regionais e globais.</div>';
 const list=(state.cards||[]).map(c=>`<article class="card-review"><div><b>${safe(c.holder_name)}</b><p>${safe(c.email||'')} · ${safe(regionName(c.region))} · ${safe(c.currency)}</p><small>${safe(c.status)} · ${safe(c.account_id.slice(0,9))}</small></div>${c.status==='REQUESTED'?`<div class="review-buttons"><button data-card-review="${safe(c.id)}" data-approve="true" class="btn btn-main">Aprovar</button><button data-card-review="${safe(c.id)}" data-approve="false" class="btn btn-ghost">Recusar</button></div>`:''}</article>`).join('')||'<div class="empty">Ainda não há pedidos de cartão.</div>';
 return `<div class="panel card-page"><div class="section-title"><h3>Aprovação de cartões digitais</h3></div><p class="muted">Aprova apenas pedidos da tua região. Os cartões são exclusivamente académicos e não funcionam em Visa/Mastercard.</p>${list}</div>`}
 const accounts=state.accounts||[];const opts=accounts.map(a=>`<option value="${safe(a.id)}">${safe(branchName(a.branch))} · ${safe(a.currency)} · ${safe(a.id.slice(0,8))}</option>`).join('');
 const items=(state.cards||[]).map(c=>`<div class="card-display">${cardVisual(c)}<div class="card-info"><b>${safe(c.status==='REQUESTED'?'A aguardar aprovação do gerente':c.status==='ACTIVE'?'Cartão activo':c.status==='FROZEN'?'Cartão congelado':c.status==='REJECTED'?'Pedido recusado':'Cartão cancelado')}</b><p>Conta: ${safe(branchName(c.branch))} · ${safe(c.currency)}. O cartão não dispõe de PAN/CVV válidos.</p>${c.status==='ACTIVE'||c.status==='FROZEN'?`<button class="btn btn-ghost" data-card-freeze="${safe(c.id)}" data-mode="${c.status==='ACTIVE'?'freeze':'unfreeze'}">${c.status==='ACTIVE'?'Congelar cartão':'Descongelar cartão'}</button>`:''}</div></div>`).join('');
 return `<div class="card-page"><div class="panel"><div class="section-title"><h3>Os meus cartões digitais</h3><span class="muted">Emissão académica</span></div><p class="guidance">Os cartões são emitidos para demonstração e só ficam activos após aprovação do gerente. Não permitem compras reais.</p>${items||'<div class="empty">Ainda não tens cartões. Faz um pedido para a tua conta.</div>'}</div><div class="panel"><h3>Solicitar novo cartão</h3><form id="requestCardForm" class="form"><label>Conta associada<select id="requestCardAccount" required>${opts}</select></label><button class="btn btn-main" ${opts?'':'disabled'}>Solicitar cartão virtual</button></form></div></div>`}
async function requestCard(e){e.preventDefault();try{await jsonPost('/api/cards/request',{account_id:formValue('requestCardAccount')});show('Pedido enviado ao gerente da região.');await sync()}catch(e){show(e.message,'error')}}
async function reviewCard(id,approved){try{await jsonPost('/api/admin/cards/'+id+'/review',{approved});show(approved?'Cartão aprovado':'Pedido recusado');await sync()}catch(e){show(e.message,'error')}}
async function toggleCard(id,action){try{await jsonPost('/api/cards/'+id+'/'+action,{});show(action==='freeze'?'Cartão congelado':'Cartão desbloqueado');await sync()}catch(e){show(e.message,'error')}}

function render(){if(!person()){$('app').innerHTML=state.publicPage==='landing'?landingPage():'<div class="back-home"><button onclick="showLanding()">← Voltar ao início</button></div>'+getAuth();return}const pages={dashboard:staff()?dashboardManager:dashboardClient,cards:cardsPage,services:servicesPage,accounts:accountsPage,transfer:transferPage,movements:movementsPage,nodes:nodePage,ops:opsPage,clients:clientsPage,teller:tellerPage,exchange:exchangePage,receipt:receiptPage,about:aboutPage};$('app').innerHTML=`<div class="logged ${staff()?'nb-manager-mode':''}">${header()}${!staff()&&state.page!=='transfer'?failoverNotice(false):''}${(pages[state.page]||dashboardClient)()}${footer()}</div>`;bindPage()}
function goto(page){state.page=page;state.mobileNav=false;state.beneficiary=null;state.quote=null;render();if(page==='movements')loadLedger();window.scrollTo(0,0)}
async function copyValue(text){try{await navigator.clipboard.writeText(text);show('Identificador copiado')}catch{show('Não foi possível copiar. Selecciona o texto manualmente.','error')}}
async function sync(silent=false){if(!state.token||state.busy)return;state.busy=true;try{
  const p=await request('/api/me');state.profile=p;state.accounts=p.accounts||[];
  if(staff()){
    const previous=state.nodes||[];
    const [stats,nodes,transfers,operations,adminAccounts,rates]=await Promise.all([request('/api/admin/stats'),request('/api/admin/nodes'),request('/api/transfers'),request('/api/admin/operations'),request('/api/admin/accounts'),request('/api/fx/rates')]);
    Object.assign(state,{stats,nodes,transfers,operations,adminAccounts,rates,failover:nodes});
    state.cards=await request('/api/admin/cards').catch(()=>[]);state.nodeActions=await request('/api/admin/node-actions').catch(()=>({agent_online:false,jobs:[]}));
    for(const n of nodes){
      const old=previous.find(x=>x.region===n.region);
      if(n.primary_status==='DOWN'&&(!old||old.primary_status==='UP'||old.primary_status==='CHECKING'))
        show(`${n.name}: servidor principal em baixo. O secundário está a assumir o serviço.`, 'warning');
      else if(old?.primary_status==='DOWN'&&n.primary_status==='UP')
        show(`${n.name}: servidor principal recuperado.`, 'success');
    }
  }else{
    const previous=state.failover||[];
    const [transfers,failover]=await Promise.all([request('/api/transfers'),request('/api/failover/status')]);
    state.transfers=transfers;state.failover=failover;state.cards=await request('/api/cards').catch(()=>[]);
    for(const n of failover){const old=previous.find(x=>x.region===n.region);if(old?.primary_status==='DOWN'&&n.primary_status==='UP')show(`${n.name}: serviços do nó principal restabelecidos.`,'success');}
  }
  state.lastUpdate=new Date().toLocaleTimeString('pt-PT');
  if(!silent||['dashboard','nodes','ops','clients','accounts','cards','services'].includes(state.page))render();
  else if(state.page==='transfer'){
    const current=$(staff()?'managerFailoverNotice':'clientFailoverNotice');
    if(current){const holder=document.createElement('div');holder.innerHTML=failoverNotice(staff());current.replaceWith(holder.firstElementChild)}
  }
 }catch(e){if(!silent)show(e.message,'error')}finally{state.busy=false}}
async function lookup(){state.beneficiary=null;state.quote=null;const id=formValue('transferDest').trim();if(!id)return;try{const b=await request('/api/accounts/lookup/'+encodeURIComponent(id));state.beneficiary=b;$('beneficiaryResult').innerHTML=`<div class="beneficiary">${ico('check',17)} ${safe(b.beneficiary)} · ${safe(branchName(b.branch))} (${safe(b.currency)})</div>`}catch(e){show(e.message,'error')}}
async function quoteTransfer(e){e.preventDefault();if(!state.beneficiary)await lookup();if(!state.beneficiary)return;try{
 const source=state.accounts.find(a=>a.id===formValue('transferSource'));
 const quote=await request('/api/fx/quote?'+new URLSearchParams({source:source.currency,destination:state.beneficiary.currency,amount:formValue('transferAmount')}));
 state.quote=quote;
 $('quoteResult').className='quote-details';$('quoteResult').innerHTML=`<div class="rate-chip">CÂMBIO ${safe(quote.fx_source)}</div><div class="quote-row"><span>Montante enviado</span><strong>${safe(quote.source_amount)} ${safe(quote.source_currency)}</strong></div><div class="quote-row"><span>Comissão (1%)</span><strong>${safe(quote.fee)} ${safe(quote.source_currency)}</strong></div><div class="quote-row"><span>Total debitado</span><strong>${safe(quote.total_debit)} ${safe(quote.source_currency)}</strong></div><div class="quote-row"><span>Conversão</span><strong>1 ${safe(quote.source_currency)} = ${safe(quote.rate)} ${safe(quote.destination_currency)}</strong></div><div class="receive"><small>O beneficiário receberá</small><h2>${safe(quote.recipient_amount)} ${safe(quote.destination_currency)}</h2></div><div class="hint">${safe(quote.notice)}</div><button id="confirmTransfer" class="btn btn-main full">${ico('shield',17)} Confirmar transferência</button>`;
 $('confirmTransfer').addEventListener('click',sendTransfer);
 }catch(e){show(e.message,'error')}}
async function createAdditionalAccount(e){e.preventDefault();try{
  await jsonPost('/api/accounts',{branch:formValue('newAccountBranch'),currency:formValue('newAccountCurrency')});
  show('Conta criada com saldo inicial zero.');await sync();goto('accounts')
 }catch(err){show(err.message,'error')}}
async function sendTransfer(){if(!state.quote||state.busy)return;const amount=formValue('transferAmount'),src=formValue('transferSource'),dst=formValue('transferDest');state.busy=true;try{
 const r=await jsonPost('/api/transfers',{source_id:src,destination_id:dst,amount,note:formValue('transferNote'),idempotency_key:state.key});
 state.receipt=r;
 if(r.status==='COMMITTED'){state.key=newUUID();show('Transferência concluída. Comprovativo disponível.');state.page='receipt'}
 else if(r.status==='ABORTED'){state.key=newUUID();show(r.error||'Operação recusada sem débito.','error');state.quote=null;state.page='transfer'}
 else{show('Operação em recuperação. Não efectues outra transferência com novo ID até verificares o estado.','warning');state.page='receipt'}
 state.busy=false;await sync();render();
 }catch(e){show(e.message,'error');state.busy=false}}
async function submitTeller(e){e.preventDefault();if(state.busy)return;state.busy=true;try{
 const kind=formValue('tellerKind'),account_id=formValue('tellerAccount'),amount=formValue('tellerAmount'),currency=formValue('tellerCurrency');
 const r=await jsonPost('/api/teller/'+(kind==='DEPOSIT'?'deposit':'withdraw'),{account_id,amount,currency,idempotency_key:state.tellerKey});
 state.tellerKey=newUUID();state.busy=false;show('Operação concluída. Saldo: '+cash(r.balance_minor,r.quote.destination_currency));await sync();goto('teller');
 }catch(e){state.busy=false;show(e.message,'error')}}
async function pdf(id){try{const r=await fetch('/api/transactions/'+id+'/receipt.pdf',{headers:{Authorization:'Bearer '+state.token}});if(!r.ok)throw Error('Comprovativo indisponível');const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='nandbank-'+id.slice(0,8)+'.pdf';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}catch(e){show(e.message,'error')}}
async function loadLedger(){const id=formValue('ledgerSelect')||state.accountSelected||state.accounts[0]?.id;state.accountSelected=id;if(!id)return;try{const rows=await request('/api/accounts/'+id+'/ledger');const target=$('ledgerData');if(!target)return;target.className='';target.innerHTML=rows.map(l=>`<div class="transaction-item"><div class="trans-icon">${ico(l.delta_minor>0?'plus':'transfer',17)}</div><div class="grow"><strong>${safe(l.kind.replaceAll('_',' '))}</strong><small>${prettyDate(l.created_at)} · ${safe(l.operation_id.slice(0,8))}</small></div><strong class="${l.delta_minor>0?'positive':'negative'}">${l.delta_minor>0?'+':''}${cash(l.delta_minor,l.currency)}</strong></div>`).join('')||'<div class="empty">Sem movimentos nesta conta.</div>'}catch(e){show(e.message,'error')}}
async function refreshFX(){try{const r=await jsonPost('/api/admin/fx/sync',{});show('Actualizadas: '+(r.updated.join(', ')||'nenhuma moeda'));await sync()}catch(e){show(e.message,'error')}}
async function updateFX(e){e.preventDefault();try{await jsonPost('/api/admin/fx/rates',{currency:formValue('fxEditCurrency'),units_per_eur:formValue('fxEditValue')});show('Taxa actualizada');await sync()}catch(e){show(e.message,'error')}}
function bindPage(){document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>goto(b.dataset.nav)));document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',()=>copyValue(b.dataset.copy)));document.querySelectorAll('[data-pdf]').forEach(b=>b.addEventListener('click',()=>pdf(b.dataset.pdf)));document.querySelectorAll('[data-account-details]').forEach(b=>b.addEventListener('click',()=>openAccountDetails(b.dataset.accountDetails)));
 $('logout')?.addEventListener('click',logout);$('refresh')?.addEventListener('click',()=>sync());$('manual-refresh')?.addEventListener('click',()=>sync());$('hamburger')?.addEventListener('click',()=>{state.mobileNav=!state.mobileNav;render()});$('overlay')?.addEventListener('click',()=>{state.mobileNav=false;render()});$('toggleBalance')?.addEventListener('click',()=>{state.visible=!state.visible;render()});document.querySelectorAll('[data-account-select]').forEach(b=>b.addEventListener('click',()=>{state.accountSelected=b.dataset.accountSelect;render()}));$('dashboardAccountSelector')?.addEventListener('change',e=>{state.accountSelected=e.target.value;render()});
 $('verifyDest')?.addEventListener('click',lookup);$('transferForm')?.addEventListener('submit',quoteTransfer);$('transferDest')?.addEventListener('input',()=>{state.beneficiary=null;state.quote=null;$('beneficiaryResult').innerHTML=''});$('transferAmount')?.addEventListener('input',()=>{state.quote=null});$('tellerForm')?.addEventListener('submit',submitTeller);$('additionalAccountForm')?.addEventListener('submit',createAdditionalAccount);$('ledgerSelect')?.addEventListener('change',loadLedger);$('getPDF')?.addEventListener('click',()=>pdf(state.receipt.id));$('refreshFx')?.addEventListener('click',refreshFX);$('fxEditForm')?.addEventListener('submit',updateFX);$('normalizeCurrencies')?.addEventListener('click',normalizeCurrencies);
 document.querySelectorAll('[data-card-flip]').forEach(b=>b.addEventListener('click',()=>b.classList.toggle('flipped')));
 document.querySelectorAll('[data-card-freeze]').forEach(b=>b.addEventListener('click',()=>toggleCard(b.dataset.cardFreeze,b.dataset.mode)));
 document.querySelectorAll('[data-card-review]').forEach(b=>b.addEventListener('click',()=>reviewCard(b.dataset.cardReview,b.dataset.approve==='true')));
 $('requestCardForm')?.addEventListener('submit',requestCard);$('nodeControlForm')?.addEventListener('submit',nodeControl);
}
async function init(){state.publicPage='landing';render();try{state.config=await request('/api/config');if(state.token)await sync();else render()}catch(e){show(e.message,'error')}}
setInterval(()=>{if(state.token&&!state.busy)sync(true)},3500);
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
init();
